function c(r,t){if(!t)return!1;if(r.correct_answer.trim().toUpperCase()===t||r.correct_answer.trim().toUpperCase().startsWith(t+".")||r.correct_answer.trim().toUpperCase().startsWith(t+")"))return!0;const e=["A","B","C","D"].indexOf(t.toUpperCase());if(e>=0&&e<r.options.length){const o=r.options[e];if(o.trim()===r.correct_answer.trim())return!0;const i=o.replace(/^[A-D][\.\)]\s*/i,"").trim().toLowerCase(),n=r.correct_answer.replace(/^[A-D][\.\)]\s*/i,"").trim().toLowerCase();if(i===n)return!0}return!1}export{c as i};
